import sys
from collections import deque

def is_connected(start, end, total_nodes, edges, blocked):
    """BFS to check if end is reachable from start, avoiding blocked edges"""
    if start == end:
        return True

    visited = [False] * (total_nodes + 1)
    visited[start] = True
    queue = deque([start])

    while queue:
        node = queue.popleft()
        for u, v, _, idx in edges:
            if idx in blocked:
                continue
            if visited[v]:
                continue
            if node == u:
                visited[v] = True
                queue.append(v)
                if v == end:
                    return True
            elif node == v:
                visited[u] = True
                queue.append(u)
                if u == end:
                    return True

    return False

