            edges.append((parts[0], parts[1], parts[2], i + 1))

    # Check if already disconnected
    if not is_connected(s, t, n, edges, set()):
        return "0\n0\n"

    best_cost = float('inf')
    best_road_idx = 3
    best_roads = []

    # Try removing 1 road
    for i in range(m):
        blocked = {i + 1}
        if not is_connected(s, t, n, edges, blocked):
            cost = edges[i][2]
            if cost < best_cost:
                best_cost = cost
                best_road_idx = i + 1
                best_roads = [i + 1]

    # Try removing 2 roads
    for i in range(m):
        for j in range(i + 1, m):
            blocked = {i + 1, j + 1}
            if not is_connected(s, t, n, edges, blocked):
                cost = edges[i][2] + edges[j][2]
