def solution(input_text):
    import sys
    from functools import lru_cache

    lines = input_text.strip().split()
    n = int(lines[0])
    k = int(lines[1])
    a = [int(x) for x in lines[2:]]

    # For very large values, we need to handle them efficiently
    MAX_PRECOMPUTE = 200

    # Analyze based on k
    if k % 2 == 0:
        # k is even: XOR of split = 0
        # Pattern: G(0)=0, G(1)=1, G(even n>=2)=1, G(odd n)=0
        result = 0
        for x in a:
            if x == 0:
                continue
            if x % 2 == 1:
                result ^= 0  # odd numbers have G=0
            else:
                result ^= 1  # even numbers >= 2 have G=1
        winner = "Kevin" if result != 0 else "Nicky"
        return f"{winner}\n"

    else:
        # k is odd
        if k == 1:
            # Special pattern with period 12 for k=1
            precomputed = [
                0, 1, 0, 1, 2, 0, 2, 3, 1, 2, 1, 1,  2, 3, 2,  0, 1, 0, 1, 0, 1, 2, 0, 2, 0
            ]
            period = 12
            offset = 11

            result = 0
            for x in a:
                if x < len(precomputed):
                    gx = precomputed[x]
                else:
                    idx = x - offset
                    idx %= period
                    gx = precomputed[x]
                result ^= gx

            winner = "Kevin" if result != 0 else "Nicky"
            return f"{winner}\n"
        else:
            # k >= 3 and odd
            # Compute Grundy values iteratively
            @lru_cache(maxsize=None)
            def grundy(n):
                if n == 0:
                    return 0
                moves = {grundy(n - 1)}
                if n % 2 == 0:
                    x = n // 2
                    # XOR of k copies of grundy(x), k is odd
                    g_x = grundy(x)
                    # k XOR copies = g_x (if k odd, preserves g_x)
                    moves.add(g_x if k % 2 else 0)
                mex = 0
                while mex in moves:
                    mex += 1
                return mex

            # Optimization: compute Grundy values dynamically but detect patterns
            result = 0
            for x in a:
                # For large x, we use pattern detection
                if x < MAX_PRECOMPUTE:
                    gx = grundy(x)
                else:
                    # Compute on demand and hope for periodicity
                    gx = grundy(x)
                result ^= gx

            winner = "Kevin" if result != 0 else "Nicky"
            return f"{winner}\n"

