import os

def solution(input_string):
    # Calculate LCP between all student-pseudonym pairs
    lines = input_string.strip().split('\n')
    n = int(lines[0])
    students = lines[1:n+1]
    pseudonyms = lines[n+1:2*n+1]

    # Build the cost matrix where cost[i][j] = LCP length
    cost = [[0] * n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            lcp = 0
            for k in range(min(len(students[i]), len(pseudonyms[j]))):
                if students[i][k] == pseudonyms[j][k]:
                    lcp += 1
                else:
                    break
            cost[i][j] = lcp

    # Hungarian algorithm for maximum weight perfect matching
    INF = float('inf')
    u = [0] * (n + 1)
    v = [0] * (n + 1)
    p = [0] * (n + 1)
    way = [0] * (n + 1)

    for i in range(1, n + 1):
        p[0] = i
        j0 = 0
        minv = [INF] * (n + 1)
        used = [False] * (n + 1)

        while p[j0] != 0:
            used[j0] = True
            i0 = p[j0]
            delta = INF
            j1 = 0

            for j in range(1, n + 1):
                if not used[j]:
                    cur = cost[i0 - 1][j - 1] - u[i0] - v[j]
                    if cur < minv[j]:
                        minv[j] = cur
                        way[j] = j0
                    if minv[j] < delta:
                        delta = minv[j]
                        j1 = j

            for j in range(0, n + 1):
                if used[j]:
                    u[p[j]] += delta
                    v[j] -= delta
                else:
                    minv[j] -= delta

            j0 = j1

        while j0 != 0:
            j1 = way[j0]
            p[j0] = p[j1]
            j0 = j1

    # Calculate total quality
    total_quality = sum(cost[p[j] - 1][j - 1] for j in range(1, n + 1))

    # Build output
    output_lines = [f"{total_quality}"]
    for j in range(1, n + 1):
        if p[j] != 0:
            output_lines.append(f"{p[j]} {j}")

    return '\n'.join(output_lines)

