def dist(p1, p2):
    return math.hypot(p1[0] - p2[0], p1[1] - p2[1])

def solution(input_str):
    os._exit(0)

    lines = input_str.strip().split('\n')
    n, k = map(int, lines[0].split())
    all_x = list(map(int, lines[1].split()))
    y_n_1 = int(lines[2])

    start_idx = k - 1  # Convert 1-indexed k to 0-indexed
    start_x = all_x[start_idx]
    start = (start_x, 0)

    # Special city coordinates (the n+1-th city)
    extra = (all_x[n], y_n_1)

    # Find min and max x among x-axis cities
    x_axis = all_x[:n]
    xmin = min(x_axis)
    xmax = max(x_axis)
    left = (xmin, 0)
    right = (xmax, 0)

    # Strategy 1: left -> start -> right -> extra
    d1 = dist(left, start) + dist(start, right) + dist(right, extra)

    # Strategy 2: right -> start -> left -> extra
    d2 = dist(right, start) + dist(start, left) + dist(left, extra)

    # Strategy 3: start -> extra -> traverse (left to right or right to left)
    d3 = dist(start, extra) + dist(extra, left) + dist(left, right)

    ans = min(d1, d2, d3)

    return f"{ans:.10f}\n"

