def solution(input_str):
    """
    Solve the stable roommates problem for city pairings.
    Returns pairing as N integers (city each city pairs with) or -1 if no stable matching exists.
    """
    import sys
    from itertools import permutations

    lines = input_str.strip().split('\n')
    n = int(lines[0])

    if n < 2:
        return "-1\n"

    # Build cost matrix (1-indexed)
    cost = [[0] * (n + 1) for _ in range(n + 1)]
    for i in range(1, n + 1):
        values = list(map(int, lines[i].split()))
        current_col = 0

        for j in range(1, n + 1):
            if i == j:
                continue
            if current_col < len(values):
                cost[i][j] = values[current_col]
                current_col += 1

    # Try all possible perfect matchings (permutations of positions)
    for perm in permutations(range(n)):
        # Create reciprocal matching (both directions)
        matching = {}
        for i in range(n):
            city_f = i + 1
            city_t = perm[i] + 1
            matching[city_f] = city_t
            matching[city_t] = city_f

        # Check if valid (no city paired with itself)
        valid = True
        for city in range(1, n + 1):
            if matching.get(city) == city:
                valid = False
                break
        if not valid:
            continue

        # Check stability - no blocking pairs
        stable = True
        for i in range(1, n + 1):
            partner_i = matching.get(i)
            for j in range(i + 1, n + 1):
                partner_j = matching.get(j)

                # If i and j are not already paired together
                if not (i == partner_j and partner_i == j):
                    # Check if both would prefer each other over current partners
                    if cost[i][j] < cost[i][partner_i] and cost[j][i] < cost[j][partner_j]:
                        stable = False
                        break
            if not stable:
                break

        if stable:
            result = []
            for i in range(1, n + 1):
                result.append(str(matching[i]))
            return "\n".join(result) + "\n"

    # No stable matching found
    return "-1\n"

