    lines = data.strip().split('\n')
    try:
        k = int(lines[0])
        parts = lines[1].split()
        if len(parts) < 2**k:
            return "Fou\n"
        a = list(map(int, parts.strip().split()[:2**k]))
    except:
        return "Fou\n"

    n = 2 ** k

    # Validate input size and range
    if len(a) != n:
        return "Fou\n"

    for x in a:
        if x < 0 or x >= n:
            return "Fou\n"

    # XOR sum check - if XOR sum of a is not 0, no solution exists
    total_xor = 0
    for x in a:
        total_xor ^= x

    if total_xor != 0:
        return "Fou\n"

    # Backtracking to find valid permutations
    used_p = [False] * n
    used_q = [False] * n
    p = [0] * n
    q = [0] * n

    def backtrack(idx):
        if idx == n:
            return True

        for u in range(n):
            if used_p[u]:
                continue
            v = u ^ a[idx]
            if 0 <= v < n and not used_q[v]:
                used_p[u] = True
                used_q[v] = True
                p[idx] = u
                q[idx] = v

                if backtrack(idx + 1):
                    return True

                used_p[u] = False
                used_q[v] = False

        return False

    if backtrack(0):
        return "Shi\n" + " ".join(map(str, p)) + "\n" + " ".join(map(str, q)) + "\n"
    else:
        return "Fou\n"

