        adj[u].append(v)
        adj[v].append(u)

    # Find connected components
    visited = [False] * (n + 1)
    component_sizes = []

    for i in range(1, n + 1):
        if not visited[i]:
            stack = [i]
            visited[i] = True
            size = 0
            while stack:
                node = stack.pop()
                size += 1
                for neighbor in adj[node]:
                    if not visited[neighbor]:
                        visited[neighbor] = True
                        stack.append(neighbor)
            component_sizes.append(size)

    # Generate lucky numbers up to n
    lucky = []
    queue = [4, 7]
    for num in queue[:]:
        if num <= n:
            lucky.append(num)
            if num * 10 + 4 <= n:
                queue.append(num * 10 + 4)
            if num * 10 + 7 <= n:
                queue.append(num * 10 + 7)
    lucky = sorted(set(lucky))

    # DP to find minimum components for each possible sum
    # dp[sum] = minimum number of components needed to achieve that sum
    dp = {0: 0}

    for size in component_sizes:
        new_states = []
        for s, k in dp.items():
            new_sum = s + size
            new_k = k + 1
            if new_sum <= n:
                new_states.append((new_sum, new_k))

        for new_sum, new_k in new_states:
