import os

def is_prime(n):
    """Miller-Rabin primality test for deterministic results up to 3*10^18"""
    if n < 2:
        return False
    if n == 2 or n == 3:
        return True
    if n % 2 == 0:
        return False

    # Write n-1 as 2^r * d
    r, d = 0, n - 1
    while d % 2 == 0:
        r += 1
        d //= 2

    # Bases that make Miller-Rabin deterministic for n < 3*10^18
    bases = [2, 3, 5, 7, 11, 13, 17, 19, 23]

    for a in bases:
        if n <= a:
            break
        x = pow(a, d, n)
        if x == 1 or x == n - 1:
            continue
        for _ in range(r - 1):
            x = pow(x, 2, n)
            if x == n - 1:
                break
        else:
            return False
    return True

