    # Simulate year by year until we find years for all needed suffixes
    while needed - set(valid_claims.values()):
        suffixes = []
        s = str(year)
        for length in range(1, len(s) + 1):
            suffixes.append(s[-length:])

        chosen = None
        for s in suffixes:
            if s not in claimed_suffixes:
                chosen = s
                break

        if chosen is None:
            # No valid suffix for this year
            return ''

        # Check if this suffix would have been claimed by an earlier year
        if chosen in valid_claims:
            # This year's claim would conflict - skip
            year += 1
            continue

